using Microsoft.AspNetCore.Mvc;using TeamBalance.BE.Entidades;using TeamBalance.BLL;
namespace Teambalance.API.Controllers;
[ApiController,Route("api/alertas-operativas")]public class AlertasOperativasController:ControllerBase{private readonly BLLAlertaOperativa _alertas;private readonly BLLUsuario _usuarios;public AlertasOperativasController(BLLAlertaOperativa alertas,BLLUsuario usuarios){_alertas=alertas;_usuarios=usuarios;}[HttpGet("configuracion")]public IActionResult Consultar(){try{return Ok(_alertas.Consultar(Sesion()));}catch(UnauthorizedAccessException ex){return StatusCode(403,ex.Message);}}[HttpPut("configuracion")]public IActionResult Guardar([FromBody]ConfiguracionAlertaAgencia c){try{return Ok(_alertas.Guardar(c,Sesion()));}catch(UnauthorizedAccessException ex){return StatusCode(403,ex.Message);}catch(Exception ex){return BadRequest(ex.Message);}}private Usuario Sesion(){string token=Request.Headers.Authorization.ToString().Replace("Bearer ","").Trim();return _usuarios.ConsultarUsuarioSesion(token)??throw new UnauthorizedAccessException("Tu sesión ya no es válida.");}}
